<?php
/** Dry-run result value object. @package OBEngine\Safety */
namespace OBEngine\Safety;
defined( 'ABSPATH' ) || exit;
final class Dry_Run_Result {
	private $library_item_id; private $status; private $summary; private $target; private $safety_result; private $result_redacted; private $actor_id; private $created_at; private $updated_at;
	public function __construct( array $data ) { $status = isset( $data['status'] ) ? sanitize_key( (string) $data['status'] ) : Safety_Status::NOT_CHECKED; $this->library_item_id = isset( $data['library_item_id'] ) ? absint( $data['library_item_id'] ) : 0; $this->status = Safety_Status::is_valid( $status ) ? $status : Safety_Status::NOT_CHECKED; $this->summary = isset( $data['summary'] ) ? sanitize_textarea_field( wp_strip_all_tags( (string) $data['summary'] ) ) : ''; $this->target = isset( $data['target'] ) && is_array( $data['target'] ) ? $this->sanitize_target( $data['target'] ) : array(); $this->safety_result = isset( $data['safety_result'] ) && is_array( $data['safety_result'] ) ? ( new Safety_Result( $data['safety_result'] ) )->to_array() : array(); $this->result_redacted = isset( $data['result_redacted'] ) && is_array( $data['result_redacted'] ) ? $this->sanitize_result_redacted( $data['result_redacted'] ) : array(); $this->actor_id = isset( $data['actor_id'] ) ? absint( $data['actor_id'] ) : 0; $this->created_at = isset( $data['created_at'] ) ? sanitize_text_field( (string) $data['created_at'] ) : ''; $this->updated_at = isset( $data['updated_at'] ) ? sanitize_text_field( (string) $data['updated_at'] ) : ''; }
	public static function from_meta( int $library_item_id, array $meta ): self { $value = static function( array $meta, string $key ) { if ( ! isset( $meta[ $key ] ) ) { return ''; } $raw = $meta[ $key ]; return is_array( $raw ) ? (string) reset( $raw ) : (string) $raw; }; $json = $value( $meta, '_obe_dry_run_result_redacted' ); $redacted = $json ? json_decode( $json, true ) : array(); return new self( array( 'library_item_id' => $library_item_id, 'status' => $value( $meta, '_obe_dry_run_status' ), 'summary' => $value( $meta, '_obe_dry_run_summary' ), 'target' => array( 'post_type' => $value( $meta, '_obe_dry_run_target_post_type' ), 'post_status' => $value( $meta, '_obe_dry_run_target_status' ) ), 'result_redacted' => is_array( $redacted ) ? $redacted : array(), 'actor_id' => $value( $meta, '_obe_dry_run_actor_id' ), 'created_at' => $value( $meta, '_obe_dry_run_created_at' ), 'updated_at' => $value( $meta, '_obe_dry_run_updated_at' ) ) ); }
	public static function empty_for_item( int $library_item_id ): self { return new self( array( 'library_item_id' => $library_item_id, 'status' => Safety_Status::NOT_CHECKED, 'summary' => __( 'No dry-run has been performed yet.', 'ob-engine' ), 'target' => array( 'post_type' => 'post', 'post_status' => 'draft' ) ) ); }
	public function to_array(): array { return array( 'library_item_id' => $this->library_item_id, 'status' => $this->status, 'summary' => $this->summary, 'target' => $this->target, 'safety_result' => $this->safety_result, 'result_redacted' => $this->result_redacted, 'actor_id' => $this->actor_id, 'created_at' => $this->created_at, 'updated_at' => $this->updated_at ); }
	public function get_library_item_id(): int { return $this->library_item_id; } public function get_status(): string { return $this->status; } public function get_summary(): string { return $this->summary; } public function get_target(): array { return $this->target; } public function get_result_redacted(): array { return $this->result_redacted; } public function get_created_at(): string { return $this->created_at; } public function get_updated_at(): string { return $this->updated_at; } public function is_passed(): bool { return Safety_Status::PASSED === $this->status; } public function is_failed(): bool { return Safety_Status::FAILED === $this->status; }
	private function sanitize_target( array $target ): array { return array( 'post_type' => isset( $target['post_type'] ) ? sanitize_key( (string) $target['post_type'] ) : 'post', 'post_status' => isset( $target['post_status'] ) ? sanitize_key( (string) $target['post_status'] ) : 'draft' ); }
	private function sanitize_result_redacted( array $data ): array { $clean = array(); foreach ( $data as $key => $value ) { $clean[ sanitize_key( (string) $key ) ] = is_array( $value ) ? $this->sanitize_result_redacted( $value ) : sanitize_text_field( (string) $value ); } return $clean; }
}
